import 'package:flutter/material.dart';import 'package:provider/provider.dart';import '../../../core/theme/app_colors.dart';import '../../../core/theme/app_typography.dart';import '../../../core/widgets/app_button.dart';import '../../../models/branch_model.dart';import '../../../providers/branch_provider.dart';class AdminBranchesTab extends StatelessWidget {  const AdminBranchesTab({super.key});  void _showBranchDialog(BuildContext context, {BranchModel? branch}) {    final nameCtrl = TextEditingController(text: branch?.name ?? '');    final addressCtrl = TextEditingController(text: branch?.address ?? '');    final cityCtrl = TextEditingController(text: branch?.city ?? '');    final phoneCtrl = TextEditingController(text: branch?.phone ?? '');    final hoursCtrl = TextEditingController(text: branch?.openingHours ?? '9:00 AM - 8:00 PM');    showDialog(      context: context,      builder: (ctx) => AlertDialog(        title: Text(branch == null ? 'Add New Branch' : 'Edit Branch'),        content: SingleChildScrollView(          child: Column(            mainAxisSize: MainAxisSize.min,            children: [              TextField(controller: nameCtrl, decoration: const InputDecoration(labelText: 'Branch Name')),              TextField(controller: addressCtrl, decoration: const InputDecoration(labelText: 'Street Address')),              TextField(controller: cityCtrl, decoration: const InputDecoration(labelText: 'City')),              TextField(controller: phoneCtrl, decoration: const InputDecoration(labelText: 'Phone Number (e.g. +91...)')),              TextField(controller: hoursCtrl, decoration: const InputDecoration(labelText: 'Opening Hours')),            ],          ),        ),        actions: [          TextButton(onPressed: () => Navigator.of(ctx).pop(), child: const Text('Cancel')),          AppButton(            label: 'Save',            height: 38,            onPressed: () async {              if (nameCtrl.text.isNotEmpty) {                final newBranch = BranchModel(                  branchId: branch?.branchId ?? 'branch_${DateTime.now().millisecondsSinceEpoch}',                  name: nameCtrl.text.trim(),                  address: addressCtrl.text.trim(),                  city: cityCtrl.text.trim(),                  phone: phoneCtrl.text.trim(),                  openingHours: hoursCtrl.text.trim(),                  description: branch?.description ?? 'Luxury StyleHub partner salon outlet.',                  image: branch?.image ?? 'https://images.unsplash.com/photo-1560066984-138dadb4c035?w=500',                  isActive: branch?.isActive ?? true,                  createdAt: branch?.createdAt ?? DateTime.now(),                );                await context.read<BranchProvider>().saveBranch(newBranch);                if (ctx.mounted) Navigator.of(ctx).pop();              }            },          ),        ],      ),    );  }  void _toggleBranchStatus(BuildContext context, BranchModel branch) {    showDialog(      context: context,      builder: (ctx) => AlertDialog(        title: Text(branch.isActive ? 'Deactivate Branch?' : 'Activate Branch?'),        content: Text(          branch.isActive              ? 'Are you sure you want to deactivate ${branch.name}? It will no longer be available for new bookings.'              : 'Are you sure you want to activate ${branch.name}?',        ),        actions: [          TextButton(onPressed: () => Navigator.of(ctx).pop(), child: const Text('Cancel')),          AppButton(            label: 'Confirm',            height: 38,            onPressed: () async {              final updated = BranchModel(                branchId: branch.branchId,                name: branch.name,                address: branch.address,                city: branch.city,                phone: branch.phone,                openingHours: branch.openingHours,                description: branch.description,                image: branch.image,                isActive: !branch.isActive,                createdAt: branch.createdAt,              );              await context.read<BranchProvider>().saveBranch(updated);              if (ctx.mounted) Navigator.of(ctx).pop();            },          ),        ],      ),    );  }  @override  Widget build(BuildContext context) {    final branchProv = context.watch<BranchProvider>();    return Scaffold(      body: ListView.builder(        padding: const EdgeInsets.all(16),        itemCount: branchProv.branches.length,        itemBuilder: (ctx, i) {          final b = branchProv.branches[i];          return Card(            margin: const EdgeInsets.only(bottom: 12),            child: ListTile(              leading: Icon(                Icons.storefront,                color: b.isActive ? AppColors.primary : Colors.grey,              ),              title: Text(                b.name,                style: AppTypography.titleMedium.copyWith(                  color: b.isActive ? AppColors.textPrimary : Colors.grey,                ),              ),              subtitle: Text('${b.address}, ${b.city}\n${b.phone}'),              trailing: PopupMenuButton<String>(                onSelected: (val) {                  if (val == 'edit') {                    _showBranchDialog(context, branch: b);                  } else if (val == 'toggle') {                    _toggleBranchStatus(context, b);                  }                },                itemBuilder: (ctx) => [                  const PopupMenuItem(value: 'edit', child: Text('Edit')),                  PopupMenuItem(                    value: 'toggle',                    child: Text(b.isActive ? 'Deactivate' : 'Activate'),                  ),                ],              ),              isThreeLine: true,            ),          );        },      ),      floatingActionButton: FloatingActionButton.extended(        backgroundColor: AppColors.primary,        foregroundColor: Colors.white,        onPressed: () => _showBranchDialog(context),        icon: const Icon(Icons.add),        label: const Text('Add Branch'),      ),    );  }}